def parse_dfxp_time_expr(time_expr):
    if not time_expr:
        return

    mobj = re.match(r'^(?P<time_offset>\d+(?:\.\d+)?)s?$', time_expr)
    if mobj:
        return float(mobj.group('time_offset'))

    mobj = re.match(r'^(?P<hours>\d+):(?P<minutes>\d\d):(?P<seconds>\d\d(?:\.\d+)?)$', time_expr)
    if mobj:
        return (3600 * int(mobj.group('hours')) + 60 * int(mobj.group('minutes')) + float(mobj.group('seconds')))

    mobj = re.match(r'^(?P<hours>\d+):(?P<minutes>\d\d):(?P<seconds>\d\d):(?P<frames>\d+)(?:\.(?P<subframes>\d+))?$', time_expr)
    if mobj:
        # TTML's alternative clock format includes frame and subframe fields.
        # youtube-dl's DFXP handling has no frame-rate context here, so interpret
        # the frame fields as a fractional second at the conventional 30 fps.
        seconds = (3600 * int(mobj.group('hours')) + 60 * int(mobj.group('minutes')) + int(mobj.group('seconds')))
        frames = int(mobj.group('frames'))
        subframes = mobj.group('subframes')
        return seconds + (frames + (float('0.' + subframes) if subframes else 0)) / 30

